/**
 * Sort directive for analytics result sets.
 *
 * Each instance describes the logical field used for sorting and the direction
 * in which the field should be ordered. The field typically corresponds to a
 * grouping dimension key (such as period or seller) or a particular metric
 * (such as net quantity change).
 *
 * Multiple directives can be combined in an ordered list to define compound
 * ordering conditions, where earlier entries have higher precedence than later
 * ones.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IAnalyticsSort = {
  /**
   * Logical analytics field key to sort by.
   *
   * This may reference a grouping dimension, such as `period`, `plan`,
   * `seller`, `warehouse`, or `reason`, or a metric such as
   * `new_subscriptions`, `net_quantity_change`, or `event_count`.
   *
   * If the field name is not recognized by the analytics engine for the
   * current query, the request should be rejected with a validation error.
   */
  field: string;

  /**
   * Sort direction for the given field.
   *
   * Supported directions typically include `asc` for ascending and `desc` for
   * descending order. The analytics layer must treat values case-sensitively
   * or normalize them according to implementation rules.
   *
   * When omitted, the backend may default to ascending order per field.
   */
  direction?: string | undefined;
};
